根据规格（双锁 + `sa`/`sb` 握手、旁观者不持锁、输出 `DONE a=1 b=1`），完整程序如下：

```rust
use concir_sync::Semaphore;
use std::sync::{Arc, Mutex};
use std::thread;

fn a(
    a: Arc<Mutex<()>>,
    b: Arc<Mutex<()>>,
    sa: Arc<concir_sync::Semaphore>,
    sb: Arc<concir_sync::Semaphore>,
    va: Arc<Mutex<u32>>,
) {
    let p_sa = sa.acquire();
    let _ga = a.lock().unwrap();
    p_sa.release();
    let _p_sb = sb.acquire();
    let _gb = b.lock().unwrap();
    *va.lock().unwrap() = 1;
}

fn b(
    a: Arc<Mutex<()>>,
    b: Arc<Mutex<()>>,
    sa: Arc<concir_sync::Semaphore>,
    sb: Arc<concir_sync::Semaphore>,
    vb: Arc<Mutex<u32>>,
) {
    let p_sb = sb.acquire();
    let _gb = b.lock().unwrap();
    p_sb.release();
    let _p_sa = sa.acquire();
    let _ga = a.lock().unwrap();
    *vb.lock().unwrap() = 1;
}

fn bystander(flag: Arc<Mutex<u64>>) {
    loop {
        if let Ok(mut f) = flag.try_lock() {
            *f = f.wrapping_add(1);
        }
    }
}

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));
    let sa = Semaphore::new(1);
    let sb = Semaphore::new(1);
    let flag = Arc::new(Mutex::new(0u64));
    let va = Arc::new(Mutex::new(0u32));
    let vb = Arc::new(Mutex::new(0u32));

    let ha = {
        let a = Arc::clone(&a);
        let b = Arc::clone(&b);
        let sa = Arc::clone(&sa);
        let sb = Arc::clone(&sb);
        let va = Arc::clone(&va);
        thread::spawn(move || a(a, b, sa, sb, va))
    };
    let hb = {
        let a = Arc::clone(&a);
        let b = Arc::clone(&b);
        let sa = Arc::clone(&sa);
        let sb = Arc::clone(&sb);
        let vb = Arc::clone(&vb);
        thread::spawn(move || b(a, b, sa, sb, vb))
    };
    let _hbyst = {
        let flag = Arc::clone(&flag);
        thread::spawn(move || bystander(flag))
    };

    ha.join().unwrap();
    hb.join().unwrap();

    let a_count = *va.lock().unwrap();
    let b_count = *vb.lock().unwrap();
    println!("DONE a={} b={}", a_count, b_count);
}
```

说明：`sa`、`sb` 初值为 1；`a` 先占 `sa` 再锁 `a` 并释放 `sa`，等 `sb` 后再锁 `b`；`b` 对称地先占 `sb`、锁 `b`、释放 `sb`，再等 `sa`、锁 `a`，满足 R4–R5 且避免交叉等锁。旁观者只动 `flag`，不碰 `a`/`b` 锁。主线程只 join 两个 worker，最后打印 `DONE a=1 b=1`。
